(function(){'use strict';
const $=id=>document.getElementById(id),api=window.WorkspaceAPI,model=window.OfficeModel,packages=window.OwnedOfficePackages;
const money=c=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(c/100);
const params=new URLSearchParams(location.search);if(params.get('embed')==='1'){document.body.classList.add('checkout-embedded');const report=()=>parent.postMessage({type:'group-checkout-height',height:Math.max(document.body.scrollHeight,document.documentElement.offsetHeight)},location.origin);new ResizeObserver(report).observe(document.body);window.addEventListener('load',report);}
const storageKey='agenticcore.checkout.v1',wallet='0x62Ad7D55fbc8A8591109D72b67Ec63aa1EE196bC';
const uuid=()=>{if(crypto.randomUUID)return crypto.randomUUID();const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;return [...b].map((n,i)=>([4,6,8,10].includes(i)?'-':'')+n.toString(16).padStart(2,'0')).join('')};
let user=null,orgs=[],key=uuid(),busy=false,statusTimer;
async function watchOrder(o){clearTimeout(statusTimer);if(!['awaiting_payment','needs_scope','payment_review'].includes(o.status))return;statusTimer=setTimeout(async()=>{try{const fresh=(await api.order(o.id))[0];if(!fresh)return;if(fresh.status!==o.status||fresh.fulfillment_status!==o.fulfillment_status){await receipt(fresh);await orders()}else watchOrder(fresh)}catch{watchOrder(o)}},10000)}
window.addEventListener('beforeunload',()=>clearTimeout(statusTimer));
const node=(tag,text,cls)=>{const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el};
function feedback(text){$('feedback').textContent=text;if(text)$('feedback').focus()}
function config(){return {route:$('route').value,departments:[...document.querySelectorAll('[name=department]:checked')].map(i=>i.value),level:$('level').value,term:$('term').value,packageId:$('package').value}}
function selection(){return {configuration:config(),payment_method:$('method').value,schedule:$('schedule').value,requirements:$('requirements').value}}
function saveDraft(){try{sessionStorage.setItem(storageKey,JSON.stringify({...selection(),idempotency_key:key}))}catch{}}
model.departments.forEach(d=>{const card=node('div',undefined,'checkout-service'),label=node('label'),input=node('input');input.type='checkbox';input.name='department';input.value=d.id;const text=node('span');text.append(node('strong',d.name),node('small',money(d.price*100)+' / cycle at Essential · '+d.unit+' '+d.measure));label.append(input,text);const detail=node('details');detail.append(node('summary','What is included?'),node('p',d.output),node('p','Inputs: '+d.inputs),node('p','One request: '+d.oneRequest),node('p','Revisions: '+d.revision),node('p','Outside scope: '+d.outside));card.append(label,detail);$('departments').append(card)});
model.levels.forEach(l=>{const o=node('option',l.name+' — '+l.description);o.value=l.id;$('level').append(o)});
packages.forEach(p=>{const o=node('option',p.name+' — '+money(p.price*100));o.value=p.id;$('package').append(o)});
try{const saved=JSON.parse(sessionStorage.getItem(storageKey)||'null');if(saved){if(saved.idempotency_key)key=saved.idempotency_key;const c=saved.configuration||saved;for(const id of ['route','level','term'])if(c[id])$(id).value=c[id];if(c.packageId)$('package').value=c.packageId;document.querySelectorAll('[name=department]').forEach(i=>i.checked=(c.departments||[]).includes(i.value));if(saved.payment_method)$('method').value=saved.payment_method;if(saved.schedule)$('schedule').value=saved.schedule;$('requirements').value=saved.requirements||''}}catch{}
function totalLine(label,value,cls=''){const line=node('div',undefined,'checkout-total '+cls);line.append(node('span',label),node('span',money(value)));return line}
function render(){const c=config();$('managed').hidden=c.route!=='managed';$('owned').hidden=c.route!=='owned';const p=packages.find(p=>p.id===c.packageId);$('build-detail').textContent=p?p.scope+' '+p.delivery:'';$('schedule-detail').textContent=c.route==='owned'?'Four 25% milestones: kickoff/scope, prototype, integration testing, acceptance/handover.':c.term==='annual'?'Four quarterly payments at start and months 3, 6 and 9. Annual total already includes the 20% discount.':'Four weekly payments within one 28-day cycle. Each payment covers part of the same cycle allowance.';$('summary').replaceChildren();
 try{const q=window.CheckoutModel.quote(c,$('method').value,$('schedule').value,model,packages);const list=node('ul');q.items.forEach(t=>list.append(node('li',t)));$('summary').append(list,node('p',c.route==='owned'?'One-time framework build':c.term==='annual'?'365-day managed plan':'28-day managed cycle'),totalLine('Service total',q.subtotal),totalLine('AC Token discount (10%)',-q.discount),totalLine('Order total',q.total),totalLine($('schedule').value==='full'?'Amount due':'First of four payments',q.due,'due'));if($('method').value==='ac')$('summary').append(node('p','AC Token first/full payment: '+window.CheckoutModel.acTokens(q.due)+' AC (before the unique invoice reference). Fixed rate: 1 AC = $0.0000006 until 29 April 2027.','fine'));if(c.route==='owned')$('summary').append(node('p','Scope review required before payment.','fine'));$('place-order').disabled=busy||!user||!orgs.length;
 }catch(e){$('summary').append(node('p',e.message));$('place-order').disabled=true}saveDraft()}
$('checkout-form').addEventListener('input',()=>{key=uuid();render()});$('checkout-form').addEventListener('change',()=>{key=uuid();render()});
async function orders(){if(!user||!$('business').value)return;$('order-list').replaceChildren();const rows=await api.orders($('business').value);$('orders-note').textContent=rows.length?'Your latest saved orders. Payment status is updated after team verification.':'No orders yet. Choose your services above to start.';for(const o of rows){const card=node('article',undefined,'checkout-order');card.append(node('h3',o.configuration.route==='owned'?'Framework order':'Managed office order'),node('p',o.id,'order-reference'),node('p',(o.status==='awaiting_payment'&&o.office_payment_submissions?.length?'payment verification pending':o.status.replaceAll('_',' '))+' · '+money(o.total_cents)+' total · '+new Date(o.created_at).toLocaleDateString()));const b=node('button','View order / payment','outline');b.type='button';b.onclick=()=>receipt(o);card.append(b);$('order-list').append(card)}}
async function receipt(o){clearTimeout(statusTimer);const r=$('receipt');r.replaceChildren();r.hidden=false;r.append(node('p','ORDER SAVED','eyebrow'),node('h2',o.status==='paid'?'Payment confirmed':o.status==='needs_scope'?'Your framework order is under scope review.':'Your order is ready for payment.'),node('p','Order reference: '+o.id,'order-reference'));
const q=window.CheckoutModel.quote(o.configuration,o.payment_method,o.schedule,model,packages);const ul=node('ul');q.items.forEach(i=>ul.append(node('li',i)));r.append(ul,totalLine('Order total',o.total_cents),totalLine(o.schedule==='full'?'Amount due':'First payment',o.due_cents,'due'),node('p','Payment method: '+(o.payment_method==='ac'?'AC Token · 10% discount applied':'USDT · BNB Smart Chain')));
if(o.status==='needs_scope'){r.append(node('p','Send the order reference to our team to agree the framework scope, acceptance criteria, delivery schedule and support terms. Payment instructions become available after scope approval.'));}else if(o.status==='awaiting_payment'){
 const panel=node('div',undefined,'receipt-wallet'),copy=node('div');copy.append(node('p',o.expected_amount?'Send exactly '+o.expected_amount+' '+(o.payment_method==='ac'?'AC Token':'USDT')+' on BNB Smart Chain (BEP-20). The small reference fraction identifies this order; do not round it. Network fees are separate.':o.payment_method==='ac'?'This older order needs a confirmed token quote from the team.':'This older order needs manual payment confirmation from the team.'));
 const field=node('input');field.type='text';field.value=wallet;field.readOnly=true;field.setAttribute('aria-label','Receiving wallet address');const b=node('button','Copy receiving address','outline');b.type='button';const copyStatus=node('p');copyStatus.setAttribute('role','status');b.onclick=async()=>{try{await navigator.clipboard.writeText(wallet);copyStatus.textContent='Address copied.'}catch{field.select();copyStatus.textContent='Select and copy the address above.'}};copy.append(field,b,copyStatus,node('p','Use the same receiving QR. Check the token and network before sending; network fees are separate.','fine'));const image=node('img');image.src='assets/payment-wallet-bnb.jpg';image.alt='Supplied receiving wallet QR';image.width=720;image.height=884;panel.append(copy,image);r.append(panel);
 r.append(node('p','Payment detection runs automatically for invoices with an exact token amount. You can also submit the transaction hash below for support.','fine'));const proofs=await api.paymentSubmissions(o.id);if(proofs.length){r.append(node('h3','Payment submitted · verification pending'),node('p','A transaction hash has been recorded. This is not a confirmation of receipt.'));proofs.forEach(p=>r.append(node('p',p.transaction_hash,'order-reference')));}else{const form=node('form'),label=node('label','Already transferred? Enter the transaction hash');const hash=node('input');hash.type='text';hash.required=true;hash.pattern='0[xX][0-9a-fA-F]{64}';hash.placeholder='0x… (64 hexadecimal characters)';label.append(hash);const button=node('button','Submit payment for verification','dark');button.type='submit';const note=node('p');note.setAttribute('role','status');form.append(label,button,note);form.onsubmit=async e=>{e.preventDefault();if(button.disabled)return;button.disabled=true;try{await api.submitPayment(o.id,hash.value.trim());await receipt(o);await orders()}catch(e){note.textContent=e.message;button.disabled=false}};r.append(form)}
}else r.append(node('p','Current status: '+o.status.replaceAll('_',' ')));r.append(node('p','Work progress: '+(o.fulfillment_status||'pending').replaceAll('_',' ')));
 const contact=node('a','Contact the team with this order reference ↗');contact.href='https://t.me/AgenticCorebiz';r.append(contact,node('p','No automatic renewal, wallet debit or service activation. Keep your order reference and transaction hash.','fine'));r.scrollIntoView({behavior:'smooth',block:'start'});watchOrder(o)}
$('business').onchange=()=>{clearTimeout(statusTimer);$('receipt').hidden=true;key=uuid();orders().catch(e=>feedback(e.message))};
$('checkout-form').onsubmit=async e=>{e.preventDefault();if(busy||$('place-order').disabled)return;busy=true;render();feedback('');const payload={organization_id:$('business').value,idempotency_key:key,...selection()};try{let o;try{o=(await api.createOrder(payload))[0]}catch(e){const existing=await api.orders(payload.organization_id);o=existing.find(x=>x.idempotency_key===payload.idempotency_key);if(!o)throw e}if(!o)throw Error('The order could not be confirmed. Please refresh My orders before trying again.');await receipt(o);await orders();key=uuid();$('consent').checked=false;}catch(e){feedback(e.message)}finally{busy=false;render()}};
(async()=>{render();if(!api.hasSession())return;try{user=await api.user();if(!user.email_confirmed_at)throw Error('Confirm your email before checkout.');orgs=await api.organizations();$('account').replaceChildren(node('p','Signed in as '+user.email));if(!orgs.length){$('account').append(node('p','Create your business workspace first. Your checkout selection is saved.'));const a=node('a','Set up my business ↗');a.href='workspace.html?next=checkout';$('account').append(a)}else{$('business-label').hidden=false;orgs.forEach(o=>{const option=node('option',o.name);option.value=o.id;$('business').append(option)});if(orgs.some(o=>o.id===params.get('business')))$('business').value=params.get('business');await orders();const orderId=params.get('order');if(orderId){const rows=await api.orders($('business').value);const selected=rows.find(o=>o.id===orderId);if(selected)await receipt(selected)}}render()}catch(e){feedback(e.message)}})();
})();
